#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"
}
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

# ── 冒烟专用辅助：只记录计数/状态/字段，正文与预览原文绝不回显或落盘 ────────
if [[ ! -f pyproject.toml && -d macos_sync_probe ]] || [[ ! -d macos_sync_probe ]]; then
  echo "请在仓库根目录（含 macos_sync_probe/）运行本脚本。" >&2
  exit 2
fi

PROBE_BIN="macos_sync_probe/build/cli/notalone-sync-probe"
# notalone-front-sync 默认在 PATH 找 notalone-sync-probe；这里显式指向本仓构建产物。
export NOTALONE_SYNC_PROBE="$PWD/$PROBE_BIN"
LOG_DIR=".scratch/local-wechat-cli-observation/smoke"
LOG_FILE="$LOG_DIR/smoke-$(date +%Y%m%d-%H%M%S).log"
mkdir -p "$LOG_DIR"

log() { printf '[%s] %s\n' "$(date +%H:%M:%S)" "$1" | tee -a "$LOG_FILE"; }

# 探针单次定位：只输出 wechat_in_front、display_name 与其余字段"有无"。
# preview_text 的值被 jq 显式丢弃，不出现在终端或日志中。
probe_fields() {
  "$PROBE_BIN" --session --json 2>>"$LOG_FILE" | jq -r '
    if .ok == true then
      "wechat_in_front=\(.wechat_in_front)",
      "display_name=\(.display_name // "未识别")",
      "last_time_text=\(if .last_time_text == null then "无" else "有" end)",
      "preview_text=\(if .preview_text == null then "无" else "有(值不回显)" end)"
    else "ok=false error=\(.error // "unknown")" end' | tee -a "$LOG_FILE" \
    || log "probe=read_failed"
}

front_sync() {
  log "cmd: notalone-front-sync $*"
  conda run -n NotAlone notalone-front-sync "$@" 2>&1 | tee -a "$LOG_FILE"
}

# 只输出联系人范围内的消息与来源引用计数；不读取任何正文。
db_count() {
  local label="$1" contact_id="$2"
  log "db_count $label contact=$contact_id"
  conda run -n NotAlone python - "$contact_id" <<'PY' 2>&1 | tee -a "$LOG_FILE"
import os
import sys

from uuid import UUID

from notalone.runtime_config import load_project_env

load_project_env()
import psycopg

contact_id = UUID(sys.argv[1])
owner_id = UUID(os.environ["NOTALONE_OWNER_ID"])
url = os.environ["NOTALONE_DATABASE_URL"]
with psycopg.connect(url) as connection:
    exists = connection.execute(
        "SELECT count(*) FROM public.contact WHERE owner_id = %s AND id = %s",
        (owner_id, contact_id),
    ).fetchone()[0]
    messages = connection.execute(
        "SELECT count(*) FROM public.message WHERE owner_id = %s AND contact_id = %s",
        (owner_id, contact_id),
    ).fetchone()[0]
    refs = connection.execute(
        """
        SELECT count(*) FROM public.message_source_ref ref
        WHERE ref.owner_id = %s AND ref.contact_id = %s
          AND ref.source_kind = 'local_wechat_observation'
        """,
        (owner_id, contact_id),
    ).fetchone()[0]
    cursor = connection.execute(
        """
        SELECT last_local_id FROM public.wechat_observation_cursor
        WHERE owner_id = %s AND contact_id = %s
        """,
        (owner_id, contact_id),
    ).fetchone()
print(
    f"contact_exists={bool(exists)} messages={messages} "
    f"observation_refs={refs} watermark={cursor[0] if cursor else 'none'}"
)
PY
}

banner "真实微信前台同步冒烟（07）"

# ── Stage 1：预检与联系人选择 ─────────────────────────────────────────────
stage "预检与联系人选择"
say "检查探针、wechat-cli 与配置；然后选择两个一对一联系人用于冒烟。"
if [[ ! -x "$PROBE_BIN" ]]; then
  warn "探针二进制不存在：$PROBE_BIN（先运行 zsh macos_sync_probe/scripts/build_cli.sh）"
  exit 1
fi
log "probe_binary=ok"
if command -v wechat-cli >/dev/null 2>&1; then
  wechat-cli --version 2>&1 | tee -a "$LOG_FILE" || warn "wechat-cli --version 失败（继续，status 会报告 cli=unavailable）"
else
  warn "wechat-cli 不在 PATH（继续，status 会报告 cli=unavailable）"
fi
for key in NOTALONE_DATABASE_URL NOTALONE_OWNER_ID; do
  if [[ -n "$(_existing "$key" || true)" ]]; then
    log "env ${key}=已配置"
  else
    warn ".env 缺少 $key，前台同步命令无法运行。"
    exit 1
  fi
done
say ""
say "当前 owner 的联系人列表："
front_sync contacts
say ""
ask CONTACT_A "输入联系人 A 的 contact_id（UUID）:"
ask CONTACT_B "输入联系人 B 的 contact_id（只有一个联系人时直接回车跳过）:"
if [[ -n "$CONTACT_B" && "$CONTACT_A" == "$CONTACT_B" ]]; then
  warn "两个联系人不能相同。"
  exit 1
fi
log "contact_a=$CONTACT_A contact_b=${CONTACT_B:-none(单联系人模式)}"
db_count "A-基线" "$CONTACT_A"
if [[ -n "$CONTACT_B" ]]; then
  db_count "B-基线" "$CONTACT_B"
fi
note "请核对上面 contact_exists=true；为 false 说明 UUID 输错。"
pause "基线计数已记录，继续？"

# ── Stage 2：屏幕录制授权 ─────────────────────────────────────────────────
stage "屏幕录制授权"
say "探针需要屏幕录制权限。权限实际授予给'启动探针的终端程序'。"
open_url "x-apple.systempreferences:com.apple.preference.security?Privacy_ScreenCapture"
step "在打开的'屏幕录制'列表中，找到你正在使用的终端（Terminal / iTerm 等）。"
step "打开它的开关；如果列表里没有，点击 + 号把终端应用加进去。"
step "若系统要求重启终端，重启后重新运行本脚本（已记录的值会保留在日志中）。"
confirm "已授权并（如需要）重启了终端？" && log "screen_capture_permission=granted" || {
  warn "未授权，探针读取会失败；冒烟中止。"
  exit 1
}

# ── Stage 3：探针契约验证（微信非前台）────────────────────────────────────
stage "探针契约（微信非前台）"
say "先把微信切到后台（或隐藏），验证探针在无前台微信时的稳定输出。"
step "点击别的窗口或 Cmd-H 隐藏微信，确保微信不是前台应用。"
pause "微信已不在前台？"
say "探针输出（只含字段，不含预览原文）："
probe_fields
note "预期：wechat_in_front=false。若显示 true，说明微信仍在前台。"
confirm "输出符合预期（wechat_in_front=false）？" && log "stage3=pass" || log "stage3=unexpected"

# ── Stage 4：开启同步 ─────────────────────────────────────────────────────
stage "开启前台同步"
say "用户手动开启前台增量同步；关闭时不读取。"
front_sync enable
confirm "输出为 sync=enabled？" && log "stage4=pass" || log "stage4=unexpected"

# ── Stage 5：联系人 A 一次性绑定 ──────────────────────────────────────────
stage "联系人 A — 一次性绑定"
say "把微信置于前台，并打开联系人 A 的一对一聊天窗口。"
pause "微信在前台且已打开 A 的聊天？"
say "探针字段："
probe_fields
say ""
say "执行一次观察（首次绑定应输出 needs_selection 与候选）："
front_sync status
ask LOCATOR_A "复制 status 中候选的 username 并粘贴（candidate[n] username=...）:"
log "confirm A locator=$LOCATOR_A"
front_sync confirm-binding --contact-id "$CONTACT_A" --locator "$LOCATOR_A"
note "预期：phase=active、decision=confirmed_active_binding。"
say ""
if confirm "（可选）现在手动在微信里发送或接收一条 A 的文字消息，然后继续？"; then
  front_sync status
  note "预期：batch_messages≥1；本轮写入的是真实消息计数，不含正文。"
fi
db_count "A-绑定后" "$CONTACT_A"
confirm "A 的 messages/watermark 有增长（若收发了消息）？" && log "stage5=pass" || log "stage5=check-log"

# ── Stage 6：切换到联系人 B（隔离验证）────────────────────────────────────
if [[ -n "$CONTACT_B" ]]; then
stage "联系人 B — 切换与隔离"
say "在微信里切换到联系人 B 的一对一聊天窗口（不要退出微信前台）。"
pause "已切换到 B？"
say "探针字段："
probe_fields
front_sync status
ask LOCATOR_B "复制 B 的候选 username 并粘贴:"
log "confirm B locator=$LOCATOR_B"
front_sync confirm-binding --contact-id "$CONTACT_B" --locator "$LOCATOR_B"
db_count "B-绑定后" "$CONTACT_B"
db_count "A-切换后" "$CONTACT_A"
note "隔离预期：B 的计数增长进入 B 的范围；A 的 messages 不因 B 的读取变化。"
confirm "B 的 phase=active 且 A 的计数未被 B 污染？" && log "stage6=pass" || log "stage6=check-log"
else
  log "stage6=skipped(单联系人模式；切换隔离已由合成端到端测试覆盖)"
fi

# ── Stage 7：切回 A（自动确认与补读）──────────────────────────────────────
stage "切回联系人 A — 自动确认"
say "在微信里切回联系人 A 的聊天窗口。"
pause "已切回 A？"
front_sync status
note "预期：decision=confirmed_active_binding，不再要求 confirm-binding；"
note "若 A 离开期间有新消息，会以补读计数入库（来源模式在库里标记 cli_catchup）。"
db_count "A-切回后" "$CONTACT_A"
confirm "A 自动通过且计数正确？" && log "stage7=pass" || log "stage7=check-log"

# ── Stage 8：离开前台 / 回到前台 ──────────────────────────────────────────
stage "离开前台与恢复"
say "切换到任意其他应用（微信离开前台），读取应停止。"
pause "已离开微信前台？"
front_sync status
note "预期：phase=waiting_foreground、wechat_front=no，无消息写入。"
say ""
say "现在把微信切回前台（仍在 A 的会话）。"
pause "微信已回到前台？"
front_sync status
note "预期：phase=active；离开期间若有新消息，本轮以补读计数入库。"
db_count "A-回前台后" "$CONTACT_A"
confirm "离开期间不写入、回来后恢复正常？" && log "stage8=pass" || log "stage8=check-log"

# ── Stage 9：关闭同步与收尾 ───────────────────────────────────────────────
stage "关闭同步与收尾"
front_sync disable
confirm "输出为 sync=disabled？" && log "stage9=pass" || log "stage9=unexpected"
db_count "A-收尾" "$CONTACT_A"
if [[ -n "$CONTACT_B" ]]; then
  db_count "B-收尾" "$CONTACT_B"
fi
say ""
note "冒烟日志（只含计数/状态/字段）：$LOG_FILE"
note "下一步：把本日志交给代理，用于更新 spec.md 状态与记录真实字段发现。"

finish
